        :root{--bg-primary:#f0f2f5;--bg-secondary:#fff;--bg-tertiary:#e8ecef;--text-primary:#1a202c;--text-secondary:#4a5568;--text-muted:#718096;--border-color:#e2e8f0;--accent:#3b82f6;--accent-hover:#2563eb;--success:#10b981;--warning:#f59e0b;--danger:#ef4444}
        [data-theme="dark"]{--bg-primary:#1a202c;--bg-secondary:#2d3748;--bg-tertiary:#1a202c;--text-primary:#f7fafc;--text-secondary:#a0aec0;--text-muted:#718096;--border-color:#4a5568;--accent:#60a5fa;--accent-hover:#90cdf4;--success:#4ade80;--warning:#fbbf24;--danger:#f87171}
        *{margin:0;padding:0;box-sizing:border-box}
        body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:var(--bg-primary);color:var(--text-primary);transition:background .3s,color .3s}
        .app{display:flex;min-height:100vh}
        .sidebar{width:260px;background:var(--bg-secondary);border-right:1px solid var(--border-color);display:flex;flex-direction:column;position:fixed;height:100vh;z-index:100}
        .sidebar-header{padding:1.5rem;border-bottom:1px solid var(--border-color);display:flex;align-items:center;gap:.75rem}
        .logo{width:40px;height:40px;background:linear-gradient(135deg,#1e40af,#3b82f6);border-radius:8px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:1.2rem}
        .logo-text{font-size:1.25rem;font-weight:700}
        .company-text{font-size:.75rem;color:var(--text-muted);margin-top:.25rem}
        .nav-section{padding:1rem 0}
        .nav-section-title{font-size:.7rem;text-transform:uppercase;color:var(--text-muted);padding:.5rem 1.5rem}
        .nav-item{display:flex;align-items:center;gap:.75rem;padding:.75rem 1.5rem;color:var(--text-secondary);text-decoration:none;cursor:pointer;transition:all .2s}
        .nav-item:hover,.nav-item.active{background:var(--bg-tertiary);color:var(--accent)}
        .nav-item i{width:20px;text-align:center}
        .main{flex:1;margin-left:260px;display:flex;flex-direction:column}
        .header{height:64px;background:var(--bg-secondary);border-bottom:1px solid var(--border-color);display:flex;align-items:center;justify-content:space-between;padding:0 2rem;position:sticky;top:0;z-index:90}
        .header-left{display:flex;align-items:center;gap:1.5rem}
        .toggle-sidebar{padding:.5rem;border:none;background:transparent;color:var(--text-secondary);cursor:pointer;font-size:1.25rem}
        .sprint-info{display:flex;align-items:center;gap:1rem}
        .sprint-badge{background:var(--bg-tertiary);padding:.5rem 1rem;border-radius:6px;font-weight:600}
        .sprint-period{color:var(--text-muted);font-size:.875rem}
        .header-right{display:flex;align-items:center;gap:1rem}
        .theme-toggle{padding:.5rem;border:1px solid var(--border-color);background:var(--bg-secondary);color:var(--text-secondary);border-radius:6px;cursor:pointer;width:40px;height:40px;display:flex;align-items:center;justify-content:center}
        .user-avatar{width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,#1e40af,#3b82f6);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:600;font-size:.875rem}
        .dashboard{display:grid;grid-template-columns:320px 1fr;gap:1.5rem;padding:1.5rem;flex:1}
        .card{background:var(--bg-secondary);border-radius:12px;box-shadow:0 1px 3px rgba(0,0,0,.1);border:1px solid var(--border-color);overflow:hidden}
        .card-header{padding:1rem 1.5rem;border-bottom:1px solid var(--border-color);display:flex;justify-content:space-between;align-items:center}
        .card-title{font-weight:600;font-size:1rem}
        .card-body{padding:1.5rem}
        .stats-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem;margin-bottom:1.5rem}
        .stat-card{background:var(--bg-secondary);padding:1.25rem;border-radius:10px;border:1px solid var(--border-color)}
        .stat-label{font-size:.875rem;color:var(--text-muted)}
        .stat-value{font-size:1.5rem;font-weight:700;margin-top:.25rem}
        .stat-change{font-size:.75rem;margin-top:.5rem}
        .stat-change.pos{color:var(--success)}
        .stat-change.neg{color:var(--danger)}
        .chart-container{position:relative;height:280px}
        .team-list{max-height:400px;overflow-y:auto}
        .team-member{display:flex;align-items:center;gap:.75rem;padding:.75rem;border-bottom:1px solid var(--border-color)}
        .team-member:last-child{border-bottom:none}
        .team-avatar{width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,#1e40af,#3b82f6);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:600;font-size:.75rem}
        .team-info{flex:1}
        .team-name{font-weight:500;font-size:.9rem}
        .team-role{font-size:.8rem;color:var(--text-muted)}
        .team-status{width:8px;height:8px;border-radius:50%;margin-left:auto}
        .team-status.active{background:var(--success)}
        .team-status.busy{background:var(--warning)}
        .team-status.offline{background:var(--text-muted)}
        .kanban-board{display:grid;grid-template-columns:repeat(5,1fr);gap:1rem;min-height:600px}
        .kanban-column{background:var(--bg-tertiary);border-radius:10px;padding:1rem;display:flex;flex-direction:column}
        .kanban-header{font-weight:600;font-size:.875rem;margin-bottom:1rem;padding-bottom:.5rem;border-bottom:1px solid rgba(0,0,0,.1);display:flex;align-items:center;justify-content:space-between}
        .kanban-count{font-size:.75rem;color:var(--text-muted);padding:2px 8px;border-radius:10px}
        .kanban-task{background:var(--bg-secondary);border-radius:8px;padding:1rem;margin-bottom:.75rem;border:1px solid var(--border-color);cursor:grab;transition:all .2s}
        .kanban-task:hover{transform:translateY(-2px);box-shadow:0 4px 12px rgba(0,0,0,.1)}
